id_pattern = re.compile(r"events_(\d+)\.root$")

def extract_id(filename: str):
    m = id_pattern.search(filename)
    return int(m.group(1)) if m else None


exclude_ids = {int(x) for x in exclude_ids_str}
ids_linked_this_run = set()

# Log file
log_file = os.path.join(symlink_dir, "data_linking_log.txt")
with open(log_file, "w") as log:
    log.write("Dataset, Total Files, Linked File\n")

    for dataset in datasets:
        dataset_path = os.path.join(base_input_dir, dataset)
        dataset_symlink_dir = os.path.join(symlink_dir, dataset)

        if not os.path.exists(dataset_path):
            print(f"Warning: Directory {dataset_path} does not exist.")
            continue

        # Create dataset-specific folder in symlink directory
        os.makedirs(dataset_symlink_dir, exist_ok=True)

        # List and sort files
        files = sorted(os.listdir(dataset_path))
        total_files = len(files)

        if total_files == 0:
            print(f"No files in {dataset_path}.")
            continue


         # List only files that match the naming scheme and have a valid ID
        all_files = sorted(
            [f for f in os.listdir(dataset_path) if extract_id(f) is not None]
        )
        total_files = len(all_files)
        if total_files == 0:
            print(f"No matching files in {dataset_path}.")
            continue

        # Filter out excluded IDs (from eval) and any ID already selected in this run
        eligible = []
        for f in all_files:
            _id = extract_id(f)
            if _id in exclude_ids:
                continue
            if _id in ids_linked_this_run:
                continue
            eligible.append(f)

        eligible_count = len(eligible)
        need = num_files.get(dataset, 0)

        if eligible_count < need:
            print(
                f"Warning: {dataset} needs {need} files, but only {eligible_count} are eligible after filtering."
            )

        picks = eligible[-need:] if need > 0 else []

        # Create symlinks
        for f in picks:
            _id = extract_id(f)
            src = os.path.join(dataset_path, f)
            dest = os.path.join(dataset_symlink_dir, f)

            try:
                if os.path.lexists(dest):  # handles existing symlink/file
                    os.remove(dest)
                os.symlink(src, dest)
                ids_linked_this_run.add(_id)
                print(f"[{dataset}] Linked: {_id} -> {dest}")
                log.write(
                    f"{dataset},{total_files},{eligible_count},"
                    f"{len(picks)},{f},{_id},{src},{dest}\n"
                )
            except Exception as e:
                print(f"Error linking {f} in {dataset}: {e}")

